 async function renderKeepsake(){const compass=await image("/brand/keepsake-compass.png"),colors=palettes[theme],canvas=document.createElement("canvas");canvas.width=1800;canvas.height=2400;const ctx=canvas.getContext("2d")!;ctx.fillStyle=colors.paper;ctx.fillRect(0,0,1800,2400);ctx.strokeStyle=colors.accent;ctx.lineWidth=5;ctx.strokeRect(45,45,1710,2310);ctx.textAlign="center";ctx.fillStyle=colors.accent;ctx.font="22px Georgia";ctx.fillText((wedding.title||"Our Adventure Map").toUpperCase(),900,155);ctx.fillStyle=colors.ink;ctx.font="90px Georgia";ctx.fillText(`${wedding.partner_one_name} & ${wedding.partner_two_name}`,900,275);ctx.fillStyle=colors.muted;ctx.font="30px Georgia";ctx.fillText(prettyDate(wedding.wedding_date),900,335);await drawExportMap(ctx,120,420,1560,1325,colors,pins,venuePins,view,mapStyle,manual);ctx.font="36px Georgia";ctx.fillText(`✦ ${pins.filter(p=>p.category!=="Guest Origin").length} places recommended     ⌂ ${pins.filter(p=>p.category==="Guest Origin").length} guest origins     ↗ ${totalMiles.toLocaleString()} miles traveled`,900,1830);ctx.globalAlpha=.78;ctx.drawImage(compass,135,1930,235,235);ctx.globalAlpha=1;ctx.font="italic 42px Georgia";ctx.fillText("May every place carry a memory of the people who sent us there.",1000,2040);ctx.strokeStyle=colors.accent;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(150,2210);ctx.lineTo(1650,2210);ctx.stroke();ctx.font="24px Arial";ctx.fillText("MEMENTO HOUSE · MADE FOR THE MOMENT. KEPT FOR A LIFETIME.",900,2265);return canvas}
