 useEffect(()=>{let active=true;const timer=setTimeout(async()=>{try{const canvas=await renderKeepsake();if(active)setPreview(canvas.toDataURL("image/jpeg",.9));const settings={layers,theme,view,style:mapStyle,manual};const client=getSupabaseBrowserClient();const result=await client!.from("weddings").update({keepsake_settings:settings,updated_at:new Date().toISOString()}).eq("id",wedding.id).select().single();if(!result.error&&active)onWeddingChange(result.data as Wedding)}catch{}},350);return()=>{active=false;clearTimeout(timer)}},[layers,theme,view,mapStyle,manual.zoom,manual.horizontal,manual.vertical,JSON.stringify(manual.panels)])

 async function download(format:"png"|"pdf"){if(exporting)return;const delivery=prepareFileDelivery();setExporting(true);setExportError("");setExportNotice("");try{const canvas=await renderKeepsake(),blob=format==="pdf"?pdfFromCanvas(canvas):await new Promise<Blob>((resolve,reject)=>canvas.toBlob(v=>v?resolve(v):reject(new Error("PNG could not be created")),"image/png"));setExportNotice(deliverBrowserFile(blob,`${wedding.slug}-${theme}-${view}-${mapStyle}-memento-map.${format}`,delivery))}catch(e){delivery.preview?.close();setExportError((e as Error).message||"The keepsake could not be created. Please try again.")}finally{setExporting(false)}}
